import test from 'node:test';
import assert from 'node:assert/strict';
import {resolveHmaTableLayouts} from '../src/semantic.js';

// Generated bytes only. No copyrighted ROM or upstream assets.
const anchor=(name,address,format)=>({name,address,format});
const resolve=(anchors,options={})=>resolveHmaTableLayouts(anchors,{romSize:256,...options});

test('ownership fixture: adjacent disjoint tables stay independently readable',()=>{
  const result=resolve([anchor('left',16,'[value::]2'),anchor('right',24,'[value::]2')]);
  assert.equal(result.byName.size,2);
  assert.equal(result.conflicted.size,0);
  assert.equal(result.overlapWitnesses,0);
});
test('ownership fixture: nested independent table claims fail closed',()=>{
  const result=resolve([anchor('outer',16,'[value::]8'),anchor('inner',20,'[value::]2')]);
  assert.deepEqual([...result.conflicted].sort(),['inner','outer']);
});
test('ownership fixture: exact offset pointer field overlay is permitted read-only',()=>{
  const result=resolve([anchor('pointers',16,'[destination<text>]2')],{
    offsetPointers:[{address:16,offset:4}]
  });
  assert.equal(result.conflicted.size,0);
  assert.equal(result.conflictedOffsetPointers.size,0);
});
test('ownership fixture: cross-row offset pointer is unsafe',()=>{
  const result=resolve([anchor('records',16,'[byte. destination<text>]2')],{
    offsetPointers:[{address:19,offset:0}]
  });
  assert.ok(result.conflicted.has('records'));
  assert.ok(result.conflictedOffsetPointers.has(19));
});
test('ownership fixture: partially overlapping word sources invalidate dependent counts',()=>{
  const rom=new Uint8Array(256);
  rom[40]=2;rom[41]=0;rom[42]=0;
  const result=resolve([anchor('dependent',80,'[value.]counter')],{
    rom,matchedWords:[
      {name:'counter',address:40,length:2,offset:0,multOffset:1},
      {name:'counter',address:41,length:2,offset:0,multOffset:1}
    ]
  });
  // A non-authoritative read-only engine must not certify this layout.
  assert.ok(!result.byName.has('dependent')||result.conflicted.has('dependent')||
    result.wordResolution.unresolved.has('counter'));
});
test('ownership fixture: malformed dynamic format is not interpreted as free space',()=>{
  const result=resolve([anchor('unknown',16,'[nested.[field.]2]4')]);
  assert.equal(result.byName.has('unknown'),false);
});
test('ownership fixture: inspection never changes original ROM bytes',()=>{
  const rom=new Uint8Array(256);rom.set([2,0,0,0],40);
  const before=Uint8Array.from(rom);
  resolve([anchor('dependent',80,'[value.]counter')],{
    rom,matchedWords:[{name:'counter',address:40,length:4,offset:0,multOffset:1}]
  });
  assert.deepEqual(rom,before);
});

test('ownership fixture: dependent table conflicts propagate from overlapping parent',()=>{
  const result=resolve([
    anchor('parent',16,'[value::]4'),
    anchor('overlap',20,'[value::]2'),
    anchor('child',96,'[value.]parent')
  ]);
  assert.ok(result.conflicted.has('parent'));
  assert.ok(result.conflicted.has('overlap'));
  assert.ok(result.conflicted.has('child'));
});
test('ownership fixture: offset pointer conflicting with scalar field suppresses typed table',()=>{
  const result=resolve([anchor('scalar',16,'[value::]2')],{
    offsetPointers:[{address:16,offset:0}]
  });
  assert.ok(result.conflicted.has('scalar'));
  assert.ok(result.conflictedOffsetPointers.has(16));
});

test('ownership fixture: one long span conflicts with every contained table',()=>{
  const result=resolve([
    anchor('outer',8,'[value::]20'),
    anchor('innerA',16,'[value::]2'),
    anchor('innerB',40,'[value::]2'),
    anchor('innerC',64,'[value::]2')
  ]);
  for(const name of ['outer','innerA','innerB','innerC'])
    assert.ok(result.conflicted.has(name),name);
});

test('ownership fixture: unresolved named anchor inside table suppresses typed claim',()=>{
  const result=resolve([
    anchor('supported',16,'[value::]4'),
    anchor('unparsed',20,'[nested.[value.]2]4'),
    anchor('dependent',64,'[value.]supported')
  ]);
  assert.ok(result.unresolved.has('unparsed'));
  assert.equal(result.unresolvedAnchorCollisionCount,1);
  assert.ok(result.conflicted.has('supported'));
  assert.ok(result.conflicted.has('dependent'));
});
test('ownership fixture: disjoint unresolved anchor does not invalidate a table',()=>{
  const result=resolve([
    anchor('supported',16,'[value::]4'),
    anchor('unparsed',80,'[nested.[value.]2]4')
  ]);
  assert.equal(result.unresolvedAnchorCollisionCount,0);
  assert.equal(result.conflicted.has('supported'),false);
});
test('ownership fixture: unsupported anchored run at table start is not treated as a safe alias',()=>{
  const result=resolve([
    anchor('supported',16,'[value::]2'),
    anchor('unknownAlias',16,'\`lzs4x64x64\`')
  ]);
  assert.ok(result.conflicted.has('supported'));
  assert.equal(result.unresolvedAnchorCollisionCount,1);
});
